blocks.t:
limit_req_zone $binary_remote_addr zone=api:10m rate=10r/s;
limit_conn_zone $binary_remote_addr zone=conn_per_ip:10m;

server {
    location /api/ {
        limit_req zone=api burst=20 nodelay;   # 突发容忍 20，超出 503
        limit_conn conn_per_ip 10;             # 单 IP 并发连接上限
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}

# 对登录/支付等高价值接口单独收紧
location /login/ {
    limit_req zone=api burst=5 nodelay;
    # 疑似攻击时人工加封禁段（应急手段，勿当常态）
    # deny 203.0.113.0/24;  allow all;
}

server {
    listen 443 ssl;
    ssl_protocols        TLSv1.2 TLSv1.3;                 # 明确排除 1.0/1.1 与 SSLv3
    ssl_ciphers          ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305;
    ssl_prefer_server_ciphers off;   # TLS1.3 由客户端择优；1.2 段按套件列表协商
    ssl_session_timeout  1d;
    ssl_session_cache    shared:SSL:10m;
    # 证书与链（联动 4.3）：fullchain 部署，缺中间证书是经典故障
    ssl_certificate      /etc/nginx/certs/app-fullchain.pem;
    ssl_certificate_key  /etc/nginx/certs/app.key;
}
